script:
html { scroll-behavior: smooth; }
::selection { background: #FF7A1A; color: #101423; }
.cb-slab { transition: border-color 0.15s ease-out, transform 0.15s ease-out; }
.cb-slab:hover { border-color: #2036C8; transform: translateY(-2px); }
input::placeholder, textarea::placeholder { color: #9AA1B5; }
